            cout << "  ";
        }
        for(int j=0;j<=star/2;j++){
            char newAlpha = alpha + j;
            cout << newAlpha << " ";
        }
        for(int j=star/2;j>0;j--){
            char newAlpha = alpha + (j - 1);
            cout << newAlpha << " ";
        }
        for(int j=0;j<(t-star)/2;j++){
            cout << "  ";
        }
        star+=2;
        cout << endl;
    }
