int evenlyDivides(int n)
{
    int ori = n;
    int count = 0;
    while (n > 0)
    {
        int temp = n % 10;
        if (temp != 0 && ori % temp == 0)
        {
            count++;
        }
        n /= 10;
    }
    return count;
}

int reverse(int n)
{
    int ans = 0;
    int x = n;
    while (x > 0)
    {
        int temp = x % 10;
        ans = ans * 10 + temp;
        x /= 10;
    }
    if (n < 0)
    {
        cout << -1 * ans;
    }

    cout << ans;
}

bool isPalindrome(int x)
{
    long long reverse = 0;
    long long original = x;

    while (x > 0)
    {
        int temp = x % 10;
        reverse = reverse * 10 + temp;
        x /= 10;
    }
    if (original == reverse)
    {
        return true;
    }
    return false;
}
bool checkArmstrong(int n)
{
    int original = n;
    int ans = 0;
    int numDigit = 0;
    while (n > 0)
    {
        numDigit++;
        n /= 10;
    }
    n = original;
    while (n > 0)
    {
        int temp = n % 10;
        ans += pow(temp, numDigit);
        n /= 10;
    }

    if (original == ans)
        return true;
    return false;
}

int sumOfDivisors(int n)
{

    int ans = 0;
    for (int i = 1; i <= n; i++)
    {
        int sum = 0;
        for (int j = 1; j <= i; j++)
        {
            if (i % j == 0)
            {
                sum += j;
            }
        }
        ans += sum;
        sum = 0;
    }

    return ans;
}
