bool fun11(string &s,int i){
    if(i>=s.size()/2) return true;
    if(s[i]!=s[s.size()-i-1]){
        return false;
    }
    return fun11(s,i+1);
}

int fun12(int n){// fibinacci
    if(n<=1){
        return n;
    }
    return fun12(n-1) + fun12(n-2);
}

bool recursion(string &s,int i){
    int n = s.size();
    if(i>=n/2) return true;
    if(s[i]!=s[n-i-1]) return false;
    return recursion(s,i+1);
}

