long long factorial(long long n){
    if(n==1) return 1;
    return n*factorial(n-1);
}  

vector<long long> factorialNumbers(long long n) {
    vector<long long> ans;
   for(int i=1;i<=n;i++){
       long long f = factorial(i);
       if(f <= n){
           ans.push_back(f);
       }else{
           break;
       }
   }
   return ans;
}

int sumOfSeries(int n) {
    if(n==1) return 1;
    return n*n*n + sumOfSeries(n-1);
}

