void sortArrayOptimal(vector<int>& arr, int n)
{
    // tc - O(N)
    int low=0,mid=0,high=n-1;
    while(high >= mid){
        if(arr[mid]==0){
            swap(arr[low],arr[mid]);
            low++;
            mid++;
        }else if(arr[mid]==1){
