vector<int> rearrangeArrayBruteForce(vector<int>& nums) {
    // brute force tc- O(2N) , sc - O(N)
    int n = nums.size();
    vector<int>pos;
    vector<int>neg;
    for(int i=0;i<n;i++){
        if(nums[i]<0){
            neg.push_back(nums[i]);
        }else{
            pos.push_back(nums[i]);
        }
    }
    int k=0,l=0;
    for(int i=0;i<n;i++){
        if(i%2==0){
            nums[i]=pos[k];
            k++;
        }else{
            nums[i]=neg[l];
            l++;
        }
    }
    return nums;
}
