    map<int,int> mpp; // sum , index
    int sum=0;
    for(int i=0;i<n;i++){
        sum+=arr[i];
        if(sum==0){
            int startIndex = 0;
            int endIndex = i;
            int currentLength= (endIndex-startIndex) + 1;
            longest=max(longest,currentLength);
        }
        if(mpp.find(sum)!=mpp.end()){
            int startIndex = mpp[sum] + 1;
            int endIndex = i;
