int subarraysWithSumK(vector < int > a, int b) {
    // tc - O(N) sc - O(1)
    int n = a.size();
    int preSum=0;
    unordered_map<int,int> mpp; // sum(xor) , count
    mpp[0]=1;
    int ans=0;
    for(int i=0;i<n;i++){
        preSum= preSum^a[i];
        int rest = b^preSum;
        if(mpp.find(rest)!=mpp.end()){
            ans+=mpp[rest];
        }
        mpp[preSum]++;

    }
    return ans;
}

