    int missing=-1;
    int repeating=-1;
    int n = a.size();
    int arr[n+1]={0};
    for(int i=0;i<n;i++){
        arr[a[i]]+=1;
    }
    for(int i=1;i<n+1;i++){
        if(arr[i]==0) missing = i;
        if(arr[i]==2) repeating = i;
        if(missing!=-1 && repeating!=-1){
            break;
        }
    }
    return {repeating,missing};
}

