int merge(vector<int>& arr,int low,int mid,int high){
    int cnt=0;      
    int n1 = mid - low +1;
    int n2 = high - mid;
    vector<int> arr1;
    vector<int> arr2;
    for(int i=0;i<n1;i++){
        arr1.push_back(arr[low + i]);
    }
    for(int i=0;i<n2;i++){
        arr2.push_back(arr[mid + 1 + i]);
    }
    int i=0,j=0,k=low;

    while(i < n1 && j < n2){
        if(arr1[i]<=arr2[j]){
            arr[k]=arr1[i];
            k++;
            i++;
        }else{
            arr[k]=arr2[j];
