        int mid = (high+low)/2;
        if(arr[mid]==target) return mid;https://leetcode.com/problems/binary-tree-right-side-view/
        if(arr[low]<=arr[mid]){
            // sorted
            if(arr[low]<=target && target<=arr[mid]){
                high = mid - 1;
            }else{
                low = mid + 1;
            }
        }else{ // not sorted
            if(arr[mid]<=target && target<=arr[high]){
