int findMin(vector<int>& nums) {
    int n = nums.size();

    int low = 0;
    int high = n - 1;
    int ans = INT_MAX;
    while(high>=low){
        int mid = (high+low)/2;
        if(nums[low]<=nums[mid]){
            // left is sorted
            ans = min(ans,nums[low]);
            low = mid + 1;
        }else{
            // right part is sorted
            ans = min(ans,nums[mid]);
            high = mid - 1;
        }
    }
    return ans;
}
int findKRotation(vector<int> &arr) {
    int n = arr.size();
    int low = 0;
    int index = INT_MAX;
    int ans = INT_MAX;
    int high = n - 1;

    while(high>=low){
        int mid = (high+low)/2;
        if(arr[low]<=arr[mid]){
            // left part is sorted
            if(arr[low] < ans){
                ans = arr[low];
                index = low;
            }
            low = mid + 1;
        }else{
            // right part is sorted
            if(arr[mid] < ans){
                ans = arr[mid];
                index = mid;
            }
            high = mid - 1;
        }
    }
    return index;
}
int singleNonDuplicate(vector<int>& nums) {
    int n = nums.size();

    if(n==1) return nums[0];
    if(nums[0]!=nums[1]) return nums[0];
    if(nums[n-1]!=nums[n-2]) return nums[n-1];

    int low = 1;
    int high = n - 2;
    while(high>=low){
        int mid = (high+low)/2;
        if(nums[mid - 1]!=nums[mid] && nums[mid]!=nums[mid + 1]){
            return nums[mid];
        }
        // even odd - same - eliminate left - target at right
        // odd even - same - eliminate right - target at left
        if( (mid%2!=0 && nums[mid - 1]==nums[mid]) || (mid%2==0 && nums[mid]==nums[mid + 1]) ){  // even odd
            low = mid + 1;
        }else{ // odd even - same
            high = mid - 1;
        }
    }
    return -1;
}
int findPeakElement(vector<int>& nums) {
    int n = nums.size();

    if(n==1) return 0;
    if(nums[0]>nums[1]) return 0;
    if(nums[n-1]>nums[n-2]) return n-1; // all this to not write etc edge cases in below

    int low = 1;
    int high = n - 2;
    while(high>=low){
        int mid = (high+low)/2;
        if(nums[mid - 1]<nums[mid] && nums[mid]>nums[mid + 1]){
            return mid;
        }
        if(nums[mid]<nums[mid+1]){
            low = mid + 1;
        }else{
            high = mid - 1;   
        }
    }
    return -1;
}
