    DLLNode* temp =  head;
    vector<int> arr;
    while(temp->next!=NULL){
        arr.push_back(temp->data);
        temp = temp->next;
    }
    arr.push_back(temp->data);
    temp = head;
    while(temp->next!=NULL){
        int d = arr.back();
        temp->data = d;
        arr.pop_back();
        temp=temp->next;
    }
    int d = arr.back();
    temp->data = d;
    arr.pop_back();
    return head;
}



