    while(end->next!=NULL){
        e++;
        end = end->next;
    }
    vector<pair<int,int>> ans;
    while(s<e){
        if(start->data+end->data == target){
            ans.push_back({start->data,end->data});
            start=start->next;
            s++;
            end=end->prev;
            e--;
        }
        else if(start->data+end->data > target){
            e--;
            end= end->prev;
        }else{
            s++;
            start=start->next;
        }
    }
    return ans;
