ListNode* rotateRight(ListNode* head, int k) {
    if(head==NULL || head->next==NULL || k==0) return head;
    int c=0;
    ListNode* mover = head;
    ListNode* end;
    while(mover!=NULL){
        if(mover->next==NULL) end = mover;
        mover=mover->next;
        c++;
    }
    int st;
    if(c>k) st = c - k;
    if(k%c==0) return head;
    if(k>=c) {
        st = k % c;
        st = c - st;
    }
    c=1;
    mover = head;
    while(mover!=NULL){
        if(c==st){
            ListNode* temp = mover->next;
            mover->next=NULL;
            end->next = head;
            head = temp;
            break;
        }
        mover=mover->next;
        c++;
    }
    return head;
}
