        xo = xo ^ Arr[i];
    }
    long long rightMost = (xo & (xo-1))^xo;
    long long b1=0;
    long long b2=0;
    for(int i=0;i<N;i++){
        if(Arr[i] & rightMost){
            b1= b1^Arr[i]; 
        }else{
            b2=b2^Arr[i];
        }
    }
    if (b1 > b2)
        return {(int)b1, (int)b2};  // Larger first
    return {(int)b2, (int)b1};  // Larger first
} //  tc - O(2n) sc - O(1)
