 * class Node {
 * 
 * public:
 *     int data;
 *     Node* next;
 *     Node() : data(0), next(nullptr) {}
 *     Node(int x) : data(x), next(nullptr) {}
 *     Node(int x, Node* next) : data(x), next(next) {}
 * };
 * 
 * Definition of Queue
 * struct Queue {
 *   Node* front;
 *   Node* rear;
 *   void push(int);
 *   int pop();
 *   
 *   Queue() {
 *       front = rear = NULL;
 *   }
 * };
 */

 void Queue::push(int x) {
    if(front==NULL && rear==NULL){
        Node* temp = new Node(x);
        front = temp;
        rear = temp;
        return;
    }
    Node* temp = new Node(x);
    rear->next = temp;
    rear=rear->next;
}

int Queue::pop() {
    if(front==NULL){
        return -1;
    }
    Node * temp = front;
    front = front->next;
    int v = temp->data;
    delete temp;
    if(front==NULL){
        rear=NULL;
    }
    return v;
}
