        start=-1;
        end=-1;
        size=0;
        maxSize=10000;
        arr = new int[maxSize];
    }

    /*----------------- Public Functions of Queue -----------------*/

    bool isEmpty() {
        return size==0;
    }

    void enqueue(int data) {
        if(end==-1){
            start=0;
            end=0;
        }else{
            end = (end + 1) % maxSize;
        }
        arr[end]=data;
        size++;
    }

    int dequeue() {
        if(isEmpty()){
            return -1;
        }
        int c = arr[start];
        if(size==1){
            start=-1;
            end=-1;
        }else
            start = (start + 1) % maxSize;
        size--;
        return c;
    }

    int front() {
        if(isEmpty()) return -1;
        return arr[start];
    }
};
