            long long val = value;
            if(st.empty()){
                mini = val;
                st.push(val);
            }else{
                if(val > mini) st.push(val);
                else {
                    st.push(2*val - mini);
                    mini = val;
                }
            }
        }

        void pop() {
            if(st.empty()) return;

            long long v = st.top();
            st.pop();
            if(v < mini){
                mini = 2*mini - v;
            }
        }

        int top() {
            long long v = st.top();
            if(v < mini) return mini;
            return v;
        }

