                    ans+= st.top();
                    st.pop();
                }
                st.pop();
            }else{
                while(!st.empty() && priority(st.top())>=priority(c)){
                    ans+= st.top();
                    st.pop();
                }
                st.push(c);
            }
            i++;
        }
        while(!st.empty()){
            ans+=st.top();
            st.pop();
        }
        return ans;
