class Solution {
public:
    int countUnique(string s,int start){
        unordered_map<char,int> mpp;
        int c = 0 ; // count
        int n = s.length();
        for(int i=start;i<n;i++){
            mpp[s[i]]++;
            if(mpp[s[i]]==2){
                return c;
            }
            c++; // count increment
        }
        return c;
    }
    int lengthOfLongestSubstring(string s) {

        int ans = 0;
        int n = s.length();
        for(int i=0;i<n;i++){
            ans = max(ans,countUnique(s,i));
        }

        return ans;
    }
};

