class Solution {
public:
    int lengthOfLongestSubstring(string s) {

        int ans = 0;
        int n = s.length();
        unordered_map<char,int> mpp;
        int c = 0 ; // count
        int left = 0;
        for(int i=0;i<n;i++){
            mpp[s[i]]++;
            if(mpp[s[i]]==2){
                ans = max(ans,c);
                while(s[left]!=s[i]){
                    mpp[s[left]]--;
                    c--;
                    left++;
                }
                mpp[s[left]]--;
                c--;
                left++;
            }
            c++; // count increment
        }

        ans = max(ans,c);
        return ans;
    }
};

