class Solution {
public:
    int longestOnes(vector<int>& nums, int k) {
        queue<int> q;
        int ans = 0;
        int n = nums.size();
        int c = 0;
        int start = 0;
        for(int i=0;i<n;i++){
            if(nums[i]==1){
                c++;
            }else if(k>0){
                c++;
                k--;
                q.push(i);
            }else{
                ans = max(ans,c);
                if(!q.empty()){
                    int lastFlip = q.front();
                    q.pop();
                    while(start!=lastFlip){
                        start++;
                        c--;
                    }
                    start++;
                    c--;
                    q.push(i);
                    c++;
                }else{
                    c=0;
                }
            }
        }
        ans = max(ans,c);
        return ans;
    }
};

