class Solution {
public:
    int totalFruit(vector<int>& fruits) {
        int n = fruits.size();
        int ans = INT_MIN;

        for(int i=0;i<n;i++){
            pair<int,int> a = {-1,0};
            pair<int,int> b = {-1,0};
            for(int j=i;j<n;j++){
                if(fruits[j]==a.first) a.second+=1;
                else if(fruits[j]==b.first) b.second+=1;
                else if(a.first==-1){ 
                    a.first = fruits[j];
                    a.second += 1;
                }
                else if(b.first==-1) {
                    b.first = fruits[j];
                    a.second +=1;
                }
                else break;
            }
            int c = 0; // count
            if(a.first!=-1) c += a.second;
            if(b.first!=-1) c += b.second;
            ans = max(ans,c);
        }
        return ans;
    }
}

// sliding window
//  tc - O(2n)
class Solution {
public:
    int totalFruit(vector<int>& fruits) {
        int n = fruits.size();
        int ans = INT_MIN;
        unordered_map<int,int> mpp;
        int c = 0;
        int left = 0;
        for(int j=0;j<n;j++){
            mpp[fruits[j]]++;
            while(mpp.size() > 2){
                mpp[fruits[left]]--;
                if(mpp[fruits[left]]==0){
                    mpp.erase(fruits[left]);
                }
                left++;
            }
            ans = max(ans,j-left+1);
        }
        return ans;
    }
};

