class Solution {
public:
    int characterReplacement(string s, int k) {
        int ans = INT_MIN;
        int n = s.size();
        int k1 = k;
        for(char alp='A';alp<='Z';alp++){
            queue<int> q; // storeing index of char changed to uppercase
            int count = 0;
            int left = 0;
            k = k1;
            for(int right=0;right<n;right++){
                if((char)s[right]==(char)alp){
                    count++;
                }else if(k>0){
                    q.push(right);
                    k--;
                    count++;
                }else{
                    ans = max(ans,count);
                    if(!q.empty()){
                        int lastChanged = q.front();
                        q.pop();
                        while(left!=lastChanged){
                            left++;
                            count--;
                        }
                        left++;
                        count--;
                        q.push(right);
                        count++;
                    }else{
                        count = 0;
                    }
                }
            }
            ans = max(ans,count);   
        }
        return ans;
    }
};

int numSubarraysWithSum(vector<int>& nums, int goal) {
    int n = nums.size();
    int ans = 0;
    for(int i=0;i<n;i++){
        int sum = 0;
        for(int j=i;j<n;j++){
            sum += nums[j];
            if(sum==goal){
                ans++;
            }
            if(sum>goal) break;
        }
    }
    return ans;
}


