// tc - O(n) sc - O(n)
class Solution {
public:
    int numSubarraysWithSum(vector<int>& nums, int goal) {
        int n = nums.size();
        unordered_map<int,int> prefixCount;
        int sum = 0;
        int ans = 0;
        prefixCount[0]=1;
        for(int i=0;i<n;i++){
            sum+=nums[i];
            if(prefixCount.find(sum - goal)!=prefixCount.end()){
                ans += prefixCount[sum - goal];
            }
            prefixCount[sum]++;
        }
        return ans;
    }
};

int numberOfSubarrays(vector<int>& nums, int k) {
    int n = nums.size();
    int ans = 0;
    for(int i=0;i<n;i++){
        int odd = 0;
        for(int j=i;j<n;j++){
            if(nums[j]%2!=0) odd++;
            if(odd==k){
                ans++;
            }
        }
    }
    return ans;
}
