int numberOfSubarrays(vector<int>& nums, int k) {
    int n = nums.size();
    int ans = 0;
    int left = 0;
    int odd = 0;
    queue<int> q; // index
    for(int right=0;right<n;right++){
        if(nums[right]%2!=0){
            odd++;
            q.push(right);
        }
        if(odd==k){
            ans++;
            ans += q.front() - left;
        }
        if(odd>k){
            int ind = q.front();
            q.pop();
            odd--;
            left = ind+1;
            ans++;
            ans += q.front() - left;
        }
    }
    return ans;
}   

