class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.length();
        int ans = 0;
        int a = 0;
        int b = 0;
        int c = 0;
        int left = 0;
        for(int right=0;right<n;right++){
            if(s[right]=='a') a++;
            else if(s[right]=='b') b++;
            else c++;
            while(a>=1 && b>=1 && c>=1){
                ans += (n - right);
                if(s[left]=='a') a--;
                else if(s[left]=='b') b--;
                else c--;
                left++;
            }
        }
        return ans;
    }
};

