class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size(); // tc,sc - O(n),
        int ans = 0;
        vector<int> s;
        int sum = 0;
        for(int i=0;i<n;i++){ // n
            sum += cardPoints[i];
            s.push_back(sum);
        }
        // only right side
        if(n==k) ans = s[n-1];
        else ans = s[n-1] - s[n-1-k];
        int k1 = k;
        for(int i=0;i<k1;i++){ // k
            int sum = 0;
            k = k1;
            k -= i+1;
            // left
            sum += s[i];
            // right
            sum += s[n-1] - s[n-1-k];
            ans = max(ans,sum);
        }
        return ans;
    }
};

class Solution {
public:
    string minWindow(string s, string t) {
        string ans = "";
        int n = s.length();
        int m = t.length();
        unordered_map<char,int> tfreq;
        for(int i=0;i<m;i++){
            tfreq[t[i]]++;
        }
        for(int i=0;i<n;i++){
            unordered_map<char,int> subt = tfreq;
            string sub = "";
            for(int j=i;j<n;j++){
                sub+=s[j];
                if(subt.find(s[j])!=subt.end()){
                    subt[s[j]]--;
                }
                if(subt[s[j]]==0){
                    subt.erase(s[j]);
                }
                // cout << subt.size() << " " << sub << endl;
                if(subt.size()==0){
                    if(ans.length() == 0) ans = sub;
                    if(ans.length() > sub.length()) ans = sub;
                    break;
                }
            }
        }
        return ans;
    }
};
