string minWindow(string s, string t) {
    pair<int,int> ans = {-1,1}; // ans left right
    int n = s.length();
    int m = t.length();
    unordered_map<char,int> subt;
    unordered_map<char,int> tfreq;
    for(int i=0;i<m;i++){
        subt[t[i]]++;
        tfreq[t[i]]=0;
    }
    int left = 0;
    for(int right=0;right<n;right++){
        if(subt.find(s[right])!=subt.end()){
            tfreq[s[right]]++;
        }
        // validate
        int d = tfreq.size();
        for(auto it : subt){
            if(it.second <= tfreq[it.first]) d--;
            else break;
        }
        if(d==0){
            if(ans.second + ans.first == 0){
                ans.first = left;
                ans.second = right;
            }
            if(ans.second - ans.first + 1 > right-left+1) {
                ans.first = left;
                ans.second = right;
            }
            while(true){
                int wd = tfreq.size();
                for(auto it : subt){
                    if(it.second <= tfreq[it.first]) wd--;
                    else break;
                }
                if(wd!=0) break;
                // cout <<  "inside " << left<< " "<< right << " " << ans.first << " " << ans.second << endl;
                if(ans.second - ans.first + 1 > right-left+1) {
                    ans.first = left;
                    ans.second = right;
                }
                if(subt.find(s[left])!=subt.end()){
                    tfreq[s[left]]--;
                }
                left++;
            }
        }
        // cout << left<< " "<< right << " " << ans.first << " " << ans.second << endl;
    }
    if(ans.first==-1 && ans.second==1) return "";
    string ansStr = s.substr(ans.first,ans.second - ans.first + 1);
    return ansStr;
}

int minSubArrayLen(int target, vector<int>& nums) {
    int n = nums.size();
    int ans = INT_MAX;
    int sum = 0;
    int left = 0; // tc _O(n)
    for(int right=0;right<n;right++){
        sum+=nums[right];
        while(sum>=target){
            ans=min(ans,right-left+1);
            sum-=nums[left];
            left++;
        }
    }
    if(ans==INT_MAX) return 0;
    return ans;
}

int findContentChildren(vector<int>& g, vector<int>& s) {
    int ans = 0;
    int gn = g.size();
    int sn = s.size();
    sort(s.begin(),s.end());
    sort(g.begin(),g.end());
    int i=0;
    int j=0;
    while(i<gn && j<sn){
        if(g[i]<=s[j]){
            ans++;
            i++;
            j++;
        }else{
            j++;
        }
    }
    return ans;
}

