bool canJump(vector<int>& nums) {
    int n = nums.size();
    int g=n-1;
    if((n-1)==0) return true;
    for(int i=n-2;i>=0;i--){
        if((g - i)<=nums[i]) g = i;
    }
    if(g==0) return true;
    return false;
}

