// Tc - o(n^2), sc - O(n)
bool canJump(vector<int>& nums) {
    int n = nums.size();

    vector<bool> dp(n,false);
    dp[n-1]=true;
    for(int i=n-2;i>=0;i--){
        int maxReach = nums[i]+i;
        for(int j=min(n-1,maxReach);j>i;j--){
            if(dp[j]){
                dp[i]=true;
                break;
            }
        }
    }

    return false;
}

