int jump(vector<int>& nums) {
    int n = nums.size();
    int l=0;
    int r=0;
    int j=0;
    if(n-1==0) return 0;
    while(l<n && r<n){
        int l1 = l;
        int r1 = r;
        if(nums[r]>0) l = r+1;
        while(l1<=r1){
            r = max(r,l1+nums[l1]);
            l1++;
        }
        j++;
        if(r>=(n-1)) return j;
    }
    return j;
}

