TreeNode *deleteNode(TreeNode *root, int key)
{
    if (root == NULL)
        return root;
    if (root->val == key)
        return helper(root);
    TreeNode *mover = root;
    while (mover != NULL)
    {
        if (mover->val > key)
        {
            if (mover->left != NULL && mover->left->val == key)
            {
                mover->left = helper(mover->left);
            }
            else
            {
                mover = mover->left;
            }
        }
        else
        {
            if (mover->right != NULL && mover->right->val == key)
            {
                mover->right = helper(mover->right);
            }
            else
            {
                mover = mover->right;
            }
        }
    }
    return root;
}
TreeNode *helper(TreeNode *root)
{
    if (root->left == NULL)
        return root->right;
    if (root->right == NULL)
        return root->left;
    TreeNode *rightChild = root->right;
    TreeNode *lastRight = lastRightOfLeft(root->left);
    lastRight->right = rightChild;
    return root->left;
}
TreeNode *lastRightOfLeft(TreeNode *root)
{
    if (root->right == NULL)
        return root;
    return lastRightOfLeft(root->right);
}

