int orangesRotting(vector<vector<int>> &grid)
{
    int n = grid.size();
    int m = grid[0].size();
    int ans = 0;
    int freshOranges = 0;
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {
            if (grid[i][j] == 1)
                freshOranges++;
            if (grid[i][j] == 2)
                q.push({i, j});
        }
    }
    if (freshOranges == 0)
        return 0;
    while (!q.empty())
    { // contain rotten oranges
        int nq = q.size();
        for (int i = 0; i < nq; i++)
        {
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            for (int x = -1; x <= 1; x++)
            { // in four direction oranges will rote
                int nrow = row + x;
                int ncol = col + x;
                if (nrow >= 0 && nrow < n && col >= 0 && col < m && grid[nrow][col] == 1)
                {
                    freshOranges--;
                    grid[nrow][col] = 2; // rotten
                    q.push({nrow, col});
                }
                if (row >= 0 && row < n && ncol >= 0 && ncol < m && grid[row][ncol] == 1)
                {
                    freshOranges--;
                    grid[row][ncol] = 2; // rotten
                    q.push({row, ncol});
                }
            }
        }
        ans++;
    }

    if (freshOranges != 0)
        return -1;
    return ans - 1;
}

