void solve(vector<vector<char>> &board)
{
    int n = board.size();
    int m = board[0].size();
    vector<vector<int>> vis(n, vector<int>(m, 0));
    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {
            if ((i >= 1 && i < n - 1) && (j >= 1 && j < m - 1))
                continue;
            if (board[i][j] == 'O')
            {
                vis[i][j] = 1;
                q.push({i, j});
            }
        }
    }
    while (!q.empty())
    {
        int nq = q.size();
        for (int i = 0; i < nq; i++)
        {
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            vector<vector<int>> dir = {{-1, 0}, {+1, 0}, {0, -1}, {0, +1}};
            for (auto it : dir)
            {
                int nrow = row + it[0];
                int ncol = col + it[1];
                if (nrow >= 1 && nrow < n - 1 && ncol >= 1 && ncol < m - 1 && !vis[nrow][ncol] && board[nrow][ncol] == 'O')
                {
                    vis[nrow][ncol] = 1;
                    q.push({nrow, ncol});
                }
            }
        }
    }
    for (int i = 1; i < n - 1; i++)
    {
        for (int j = 1; j < m - 1; j++)
        {
            if (board[i][j] == 'O' && !vis[i][j])
            {
                board[i][j] = 'X';
            }
        }
    }
}

