int numEnclaves(vector<vector<int>> &grid)
{
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<int>> vis(n, vector<int>(m, 0)); // 1 - can walk of to boundary
    queue<pair<int, int>> q;
    for (int i = 0; i < m; i++)
        if (grid[0][i] == 1)
        {
            q.push({0, i});
            vis[0][i] = 1;
        } // top line
    for (int i = 0; i < m; i++)
        if (grid[n - 1][i] == 1)
        {
            q.push({n - 1, i});
            vis[n - 1][i] = 1;
        } // bottom line
    for (int i = 0; i < n; i++)
        if (grid[i][0] == 1)
        {
            q.push({i, 0});
            vis[i][0] = 1;
        } // left side line
    for (int i = 0; i < n; i++)
        if (grid[i][m - 1] == 1)
        {
            q.push({i, m - 1});
            vis[i][m - 1] = 1;
        } // right side line
    while (!q.empty())
    {
        int nq = q.size();
        for (int i = 0; i < nq; i++)
        {
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            vector<vector<int>> direct = {{-1, 0}, {+1, 0}, {0, -1}, {0, +1}};
            for (auto it : direct)
            {
                int nrow = row + it[0];
                int ncol = col + it[1];
                if (nrow >= 0 && nrow < n && ncol >= 0 && ncol < m && !vis[nrow][ncol] && grid[nrow][ncol] == 1)
                {
                    vis[nrow][ncol] = 1;
                    q.push({nrow, ncol});
                }
            }
        }
    } // till now we marked all land(1) which are connected to boundary
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {
            if (grid[i][j] == 1 && !vis[i][j])
                ans++;
        }
    }
    return ans;
}

int ladderLength(string beginWord, string endWord, vector<string> &wordList)
{
    int n = wordList.size();
    int nw = beginWord.length();
    unordered_set<string> words(wordList.begin(), wordList.end());
    queue<pair<string, int>> q;
    q.push({beginWord, 1});
    while (!q.empty())
    {
        int nq = q.size();
        for (int i = 0; i < nq; i++)
        {
            string w = q.front().first;
            int step = q.front().second;
            if (w == endWord)
                return step;
            q.pop();
            words.erase(w);
            for (int a = 0; a < nw; a++)
            {
                string wor = w;
                for (char d = 'a'; d <= 'z'; d++)
                {
                    wor[a] = d;
                    if (words.count(wor))
                        q.push({wor, step + 1});
                }
            }
        }
    }
    return 0;
}

