class Solution {
  public:
    vector<int> topoSort(int V, vector<vector<int>>& edges) {
        vector<int> adj[V];
        vector<int> indeg(V,0);
        for(auto it : edges){
            adj[it[0]].push_back(it[1]);
            indeg[it[1]]++;
        }
        queue<int> q;
        for(int i=0;i<V;i++){
            if(indeg[i]==0) q.push(i);
        }
        vector<int> ans;
        while(!q.empty()){
            int n = q.size();
            for(int i=0;i<n;i++){
                int a = q.front();
                q.pop();
                ans.push_back(a);
                for(auto e : adj[a]){
                    indeg[e]--;
                    if(indeg[e]==0) q.push(e);
                }
            }
        }
        return ans;
    }
};

