// Prim's Algorithm
// minimum spaning tree
// greedy - intuition
//  TC - O(E log E), Sc-O(V+E)
//  ElogE + E log E
class Solution {
  public:
    int spanningTree(int V, vector<vector<int>>& edges) {
        vector<vector<pair<int,int>>> adj(V);
        for(auto it : edges){
            int u = it[0];
            int v = it[1];
            int w = it[2];
            adj[u].push_back({v,w});
            adj[v].push_back({u,w});
        }
        priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> minHeap;
        vector<int> vis(V,0);

        int sum = 0;
        minHeap.push({0,0});
        while(!minHeap.empty()){ //E
            auto it = minHeap.top(); 
            minHeap.pop(); // log E
            int wt = it.first;
            int node = it.second;
            if(vis[node]==1) continue;
            vis[node]=1;
            sum+=wt;
            for(auto ed : adj[node]){  // E
                int adjNode = ed.first;
                int adjWt = ed.second;
                if(!vis[adjNode]){
                    minHeap.push({adjWt,adjNode}); // log E
                }
            }
        }
        return sum;

    }
};

// tc - O(4@) -- constant O(1)
class DisjointSet {
    vector<int>parent,size;
public: 
    DisjointSet(int n) {
        parent.resize(n+1);
        size.resize(n+1,1);
        for(int i=0;i<=n;i++) {
            parent[i]=i;
        }
    }
    int findUParent(int u) {
        if(parent[u]==u) {
            return u;
        }
        return parent[u]=findUParent(parent[u]);
    }
    void unionBySize(int u,int v) {
        int ulp_u=findUParent(u);
        int ulp_v=findUParent(v);

        if(ulp_u==ulp_v)
            return;
        if(size[ulp_u]<size[ulp_v]) {
            parent[ulp_u]=ulp_v;
            size[ulp_v]+=size[ulp_u];
        }
        else {
            parent[ulp_v]=ulp_u;
            size[ulp_u]+=size[ulp_v];
        }
    }
};
class Solution {
  public:
    int spanningTree(int V, vector<vector<int>>& edges) {
        // code here
        DisjointSet dsu(V);
        vector<pair<int,pair<int,int>>> ed;
        for(auto e : edges){
            ed.push_back({e[2],{e[0],e[1]}});
        }

        sort(ed.begin(),ed.end());

        int sum = 0;
        for(auto it : ed){
            int wt = it.first;
            int u = it.second.first;
            int v = it.second.second;

            if(dsu.findUParent(u)!=dsu.findUParent(v)){
                dsu.unionBySize(u,v);
                sum+=wt;
            }
        }
        return sum;
    }
};

