        int extra = 0;
        for(auto c : connections){
            if(ds.findParent(c[0])!=ds.findParent(c[1])){
                ds.unionBySize(c[0],c[1]);
            }else extra++;
        }
        int components = 0;
        for(int i=0;i<n;i++){
