class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        unordered_map<string,int> mpp;
        int n = accounts.size();
        DisjointSet ds(n);
        for(int i=0;i<n;i++){
            int m = accounts[i].size();
            for(int j=1;j<m;j++){
                string email = accounts[i][j];
                if(mpp.find(email)!=mpp.end()){
                    ds.unionBySize(mpp[email],i);
                }else mpp[email]=i;
            }
