            if(acc[p].size()==0){
                acc[p].push_back(accounts[p][0]);
                acc[p].push_back(email);
            }else acc[p].push_back(email);
        }
        for(auto a : acc){
            sort(a.second.begin()+1,a.second.end());
            if(a.second.size()!=0) ans.push_back(a.second);
        } 
        return ans;
    }
