// # Tc-O(N), Sc-O(1)
class Solution {
    public void diagonalSort(int[][] grid,int ro,int co,boolean asc){
        int n = grid.length;
        int row = ro;
        int col = co;
        int dLen = 0;
        while(row<n && col<n){
            row++;
            col++;
            dLen++;
        }
        row = ro;
        col = co;
        int[] temp = new int[dLen];
        int index = 0;
        while(row<n && col<n){
            temp[index++] = grid[row][col];
            row++;
            col++;
        }
        Arrays.sort(temp);
        if(!asc){
            for(int i=0;i<dLen/2;i++){
                int t = temp[i];
                temp[i]=temp[dLen-i-1];
                temp[dLen-i-1]=t;
            }
        }
        row =ro;
        col =co;
        index = 0;
        while(row<n && col<n){
            grid[row][col]=temp[index++];
            row++;
            col++;
        }

    }
    public int[][] sortMatrix(int[][] grid) {
        int n = grid.length;
        for(int i=0;i<n;i++){
            diagonalSort(grid,i,0,false);
        }
        for(int i=1;i<n;i++){
            diagonalSort(grid,0,i,true);
        }
        return grid;
    }
}

