    vector<int> leftView(Node *root) {
        vector<int> v;
        if(root == NULL) return v;
        queue<Node*> q;
        q.push(root);

        while(!q.empty()){
            int size = q.size();
            for(int i=0;i<size;i++){
                Node* node = q.front();
                q.pop();

                if(i == 0){
                    v.push_back(node->data);
