        q.push({sr,sc});
        while(!q.empty()){
            int row = q.front().first;
            int col = q.front().second;
            q.pop();

            for(int x = -1; x<=1; x++){
                int nrow = row + x;
                int ncol = col + x;
                if(nrow>=0 && nrow<n && col>=0 && col<m &&
                !vis[nrow][col] && image[nrow][col] == oldColor){
                    vis[nrow][col] = 1;
                    image[nrow][col] = newColor;
                    q.push({nrow,col});
