// tc - O(n*2), sc- O(n*2)

int maxProfit(vector<int>& prices) {
    int n = prices.size();
    vector<vector<int>> dp(n+1,vector<int>(2,0));
    for(int idx=n-1;idx>=0;idx--){
        for(int buy=0;buy<2;buy++){
            if(buy==1){
                int by = -prices[idx]+dp[idx+1][0];
                int notby=dp[idx+1][1];
                dp[idx][buy]=max(by,notby);
            }
            else{
                int sell = prices[idx]+dp[idx+1][1];
                int notsell= dp[idx+1][0];
                dp[idx][buy]=max(sell,notsell);
            }
        }
    }
    return dp[0][1];
}

// space optimise
// tc - O(n*2), sc- O(1)

int maxProfit(vector<int>& prices) {
    int n = prices.size();
    vector<int> ahead(2,0);
    vector<int> curr(2,0);
    for(int idx=n-1;idx>=0;idx--){
        for(int buy=0;buy<2;buy++){
            if(buy==1){
                int by = -prices[idx]+ahead[0];
                int notby=ahead[1];
                curr[buy]=max(by,notby);
            }
            else{
                int sell = prices[idx]+ahead[1];
                int notsell= ahead[0];
                curr[buy]=max(sell,notsell);
            }
        }
        ahead=curr;
    }
    return ahead[1];
}

// tc - O(n^2) Sc-O(1)
int countSubstrings(string s) {
    int n = s.length();
    int ans = 0;
    for(int i=0;i<n;i++){
        int left = i;
        int right = i;
        while(left>=0 && right<n && s[left]==s[right]){
            left--;
            right++;
            ans++;
        }
        left = i;
        right = i+1;
        while(left>=0 && right<n && s[left]==s[right]){
            left--;
            right++;
            ans++;
        }
    }
    return ans;
}

