int findAns(int i,int j,vector<vector<int>>& mat){
    if(i==0 && j==0) return 1;
    if(i<0 || j<0) return 0;
    if(mat[i][j]!=-1) return mat[i][j];

    int up = findAns(i-1,j,mat);
    int left = findAns(i,j-1,mat);

    return mat[i][j] = up+left;
}
